    "materialId": "text1",
    "id": "q-en1-2022-21",
    "subject": "en",
    "paperId": "paper-2022-en1",
    "paperOnly": true,
    "year": 2022,
    "source": "real",
    "sourceName": "2022 考研英语（一）原卷（公开网络版）",
