    "materialId": "text4",
    "id": "q-en1-2022-36",
    "subject": "en",
    "paperId": "paper-2022-en1",
    "paperOnly": true,
    "year": 2022,
    "source": "real",
    "sourceName": "2022 考研英语（一）原卷（公开网络版）",
    "sourceUrl": "https://www.yanxian.org/uploadfile/2022/1027/20221027024738287.pdf",
